SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, SUM(credit_limit) OVER (PARTITION BY segment ORDER BY credit_limit ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_credit_limit, ROW_NUMBER() OVER (PARTITION BY country ORDER BY credit_limit ASC, id ASC) AS seq_no, AVG(age) OVER (PARTITION BY segment, city ORDER BY age ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS age_avg_6, ROW_NUMBER() OVER (PARTITION BY segment ORDER BY signup_date DESC, id ASC) AS row_seq, AVG(age) OVER (PARTITION BY country ORDER BY signup_date ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS age_avg_3 FROM customers;
